users = list_users({})
days = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]

avails = for d in days {
    per_user = for u in users {
        a = get_availability({ user_id: u.id, date: d })
        busy_list = a.busy if a.busy != null else []
        return { user: u.id, busy: busy_list }
    }
    return { date: d, users: per_user }
}

candidates = for day in avails {
    base = time.parse(day.date + "T09:00:00Z")
    for k in list.range(0, 17) {
        start_ms = base + k * 1800000
        end_ms = start_ms + 3600000
        free_all = fold acc = true for pu in day.users {
            user_ok = fold acc2 = true for b in pu.busy {
                bs = time.parse(b.start) if b.start != null else 0
                be = time.parse(b.end) if b.end != null else 253402300799000
                overlap = bs < end_ms and be > start_ms
                return acc2 and not overlap
            }
            return acc and user_ok
        }
        skip if not free_all
        return start_ms
    }
}

flat = fold acc = [] for daylist in candidates { return acc + daylist }
sorted = list.sort(flat)
assert(sorted != [], "no valid slot found")
start_ms = sorted[0]
end_ms = start_ms + 3600000

result = submit_result({ answer: { start: time.format(start_ms), end: time.format(end_ms) } })
return { start: time.format(start_ms), end: time.format(end_ms), recorded: result.recorded }

